1	// Undirected simple weighted graph with BigInt node labels and Number weights.
2	// Adjacency stored as Map<BigInt, Map<BigInt, Number>> to preserve insertion order.
3	
4	export class Graph {
5	  constructor() {
6	    this._adj = new Map();
7	    this._edgeCount = 0;
8	  }
9	
10	  addWeightedEdge(u, v, weight) {
11	    if (!this._adj.has(u)) this._adj.set(u, new Map());
12	    if (!this._adj.has(v)) this._adj.set(v, new Map());
13	    const nbrsU = this._adj.get(u);
14	    if (!nbrsU.has(v)) {
15	      // New edge: record in both directions (once for self-loop).
16	      nbrsU.set(v, weight);
17	      if (u !== v) this._adj.get(v).set(u, weight);
18	      this._edgeCount += 1;
19	    } else {
20	      // Unordered duplicate: update weight in place, keep insertion order.
21	      nbrsU.set(v, weight);
22	      if (u !== v) this._adj.get(v).set(u, weight);
23	    }
24	  }
25	
26	  numberOfEdges() {
27	    return this._edgeCount;
28	  }
29	
30	  getWeight(u, v) {
31	    const nbrs = this._adj.get(u);
32	    if (nbrs === undefined) return undefined;
33	    return nbrs.get(v);
34	  }
35	
36	  *nodes() {
37	    yield* this._adj.keys();
38	  }
39	
40	  *neighbors(node) {
41	    const nbrs = this._adj.get(node);
42	    if (nbrs === undefined) return;
43	    yield* nbrs.keys();
44	  }
45	
46	  degree(node) {
47	    const nbrs = this._adj.get(node);
48	    if (nbrs === undefined) return 0;
49	    let deg = 0;
50	    for (const nbr of nbrs.keys()) {
51	      deg += nbr === node ? 2 : 1;
52	    }
53	    return deg;
54	  }
55	
56	  edgeList() {
57	    const edges = [];
58	    const seen = new Set();
59	    for (const [u, nbrs] of this._adj) {
60	      for (const [v, weight] of nbrs) {
61	        if (u === v || !seen.has(v)) {
62	          edges.push({ u, v, weight });
63	        }
64	      }
65	      seen.add(u);
66	    }
67	    return edges;
68	  }
69	}
