// Minimum spanning tree/forest using stable Kruskal's algorithm.
// Node labels are BigInt; edge weights are Number. No external modules.

export function minimumSpanningTree(graph) {
  const parent = new Map();
  const size = new Map();

  for (const node of graph.nodes()) {
    parent.set(node, node);
    size.set(node, 1);
  }

  function find(node) {
    let root = node;
    while (parent.get(root) !== root) {
      root = parent.get(root);
    }
    while (parent.get(node) !== node) {
      const next = parent.get(node);
      parent.set(node, root);
      node = next;
    }
    return root;
  }

  function union(u, v) {
    let rootU = find(u);
    let rootV = find(v);
    if (rootU === rootV) return false;

    if (size.get(rootU) < size.get(rootV)) {
      [rootU, rootV] = [rootV, rootU];
    }
    parent.set(rootV, rootU);
    size.set(rootU, size.get(rootU) + size.get(rootV));
    return true;
  }

  const sortedEdges = graph.edgeList()
    .map((edge, index) => ({ edge, index }))
    .sort((a, b) => {
      const weightDiff = a.edge.weight - b.edge.weight;
      return weightDiff !== 0 ? weightDiff : a.index - b.index;
    });

  const edges = [];
  const members = new Map();

  function addMembership(u, v) {
    if (!members.has(u)) members.set(u, new Set());
    members.get(u).add(v);
  }

  for (const { edge } of sortedEdges) {
    // NetworkX Kruskal ignores self-loops when constructing the MST.
    if (edge.u === edge.v) continue;
    if (union(edge.u, edge.v)) {
      edges.push({ u: edge.u, v: edge.v, weight: edge.weight });
      addMembership(edge.u, edge.v);
      addMembership(edge.v, edge.u);
    }
  }

  return {
    edges,
    edgeCount: edges.length,
    hasEdge(u, v) {
      const neighbors = members.get(u);
      return neighbors !== undefined && neighbors.has(v);
    },
  };
}

