node --check /output/lib/algorithms/mst.mjs && node --input-type=module -e "
import { Graph, buildGraph } from '/output/lib/graph.mjs';
import { minimumSpanningTree } from '/output/lib/algorithms/mst.mjs';

const args = { a: 1n, b: 2n, c: 3n, d: 4n, e: 5n };
const g = buildGraph(args);
const mst = minimumSpanningTree(g);
if (mst.edgeCount !== 4) throw new Error('bad edge count');
if (!mst.hasEdge(args.a, args.b) || !mst.hasEdge(args.b, args.a)) throw new Error('missing MST edge');
if (mst.hasEdge(args.a, args.e)) throw new Error('cycle edge included');
if (mst.edges.map((e) => e.weight).join(',') !== '1,2,3,4') throw new Error('bad weights');

const tied = new Graph();
tied.addWeightedEdge(10n, 11n, 1);
tied.addWeightedEdge(11n, 12n, 1);
tied.addWeightedEdge(10n, 12n, 1);
tied.addWeightedEdge(12n, 12n, 0);
const tiedMst = minimumSpanningTree(tied);
if (tiedMst.edgeCount !== 2) throw new Error('self-loop was not skipped');
if (tiedMst.edges[0].u !== 10n || tiedMst.edges[0].v !== 11n || tiedMst.edges[1].u !== 11n || tiedMst.edges[1].v !== 12n) throw new Error('unstable tie order');
console.log('mst checks passed');
"

