import { minimumSpanningTree } from '/output/lib/algorithms/mst.mjs';

const nodes = [10n, 11n, 12n, 13n];
const edgeList = [
  { u: 10n, v: 11n, weight: 1 },
  { u: 11n, v: 12n, weight: 1 },
  { u: 10n, v: 12n, weight: 1 },
  { u: 12n, v: 12n, weight: 0 },
  { u: 12n, v: 13n, weight: 2 },
];
const graph = { nodes: () => nodes[Symbol.iterator](), edgeList: () => edgeList.slice() };
const mst = minimumSpanningTree(graph);
if (mst.edgeCount !== 3) throw new Error('bad forest edge count');
if (mst.edges[0].u !== 10n || mst.edges[0].v !== 11n) throw new Error('first tie changed');
if (mst.edges[1].u !== 11n || mst.edges[1].v !== 12n) throw new Error('second tie changed');
if (mst.edges.some((e) => e.u === e.v)) throw new Error('self-loop included');
if (!mst.hasEdge(13n, 12n) || mst.hasEdge(10n, 12n)) throw new Error('bad undirected membership');
console.log('mst checks passed');
"
